    {
      struct pollfd pollfd;
      struct v4l2_buffer buffer;
      uint32_t checksum;
      uint8_t minimum;
      uint8_t maximum;

      memset(&pollfd, 0, sizeof(pollfd));
      pollfd.fd = fd;
      pollfd.events = POLLIN;
      memset(&buffer, 0, sizeof(buffer));

      ret = poll(&pollfd, 1, timeout_ms);
      if (ret == 0)
