  lv_obj_set_style_bg_opa(panel, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(panel, 1, 0);
  lv_obj_set_style_border_color(panel, COLOR_BORDER, 0);
  lv_obj_set_style_pad_all(panel, 0, 0);
  return panel;
}

