  FAR void *arg)
{
  FAR struct esp_mipi_dsi_priv_s *priv = arg;
  irqstate_t flags;

  UNUSED(chan);
  UNUSED(event_data);

  flags = spin_lock_irqsave(&priv->dmalock);
  if (priv->dma_enabled)
    {
      esp_mipi_dsi_dma_restart(priv);
