  if (frame_done)
    {
      fb_remove_paninfo(&fb->vtable, FB_NO_OVERLAY);
    }

  fb_notify_vsync(&fb->vtable);

#ifdef CONFIG_FB_SYNC
  nxsem_get_value(&fb->vsync_sem, &semcount);
  if (semcount < 1)
    {
      nxsem_post(&fb->vsync_sem);
    }
#endif
}

